"use client";

import { useState } from "react";

import { cn } from "@/lib/utils";
import { motion } from "framer-motion";

// Credit:
// https://berlix.vercel.app/docs/text-split

interface TextSplitProps {
	children: string;
	className?: string;
	topClassName?: string;
	bottomClassName?: string;
	maxMove?: number;
	falloff?: number;
}

export const TextSplit = ({
	children,
	className,
	topClassName,
	bottomClassName,
	maxMove = 50,
	falloff = 0.3,
}: TextSplitProps) => {
	const [hoverIndex, setHoverIndex] = useState<number | null>(null);

	const getOffset = (index: number) => {
		if (hoverIndex === null) return 0;
		const distance = Math.abs(index - hoverIndex);
		return Math.max(0, maxMove * (1 - distance * falloff));
	};

	return (
		<div
			className={cn("relative flex items-center justify-center ", className)}
		>
			{children.split("").map((char, index) => {
				const offset = getOffset(index);
				const displayChar = char === " " ? "\u00A0" : char;

				return (
					<div
						key={`${char}-${index}`}
						className="relative flex flex-col h-[1em] w-auto leading-none"
						onMouseEnter={() => setHoverIndex(index)}
						onMouseLeave={() => setHoverIndex(null)}
					>
						<motion.span
							initial={false}
							animate={{
								y: `-${offset}%`,
							}}
							transition={{ duration: 0.3, ease: "easeInOut" }}
							className={cn("overflow-hidden", topClassName)}
						>
							{displayChar}
						</motion.span>

						<motion.span
							initial={false}
							animate={{
								y: `${offset}%`,
							}}
							transition={{ duration: 0.3, ease: "easeInOut" }}
							className={cn("overflow-hidden", bottomClassName)}
						>
							<span className="block -translate-y-1/2">
								{displayChar}
							</span>
						</motion.span>
					</div>
				);
			})}
		</div>
	);
};

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
